import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int M = scanner.nextInt();

        List<List<Integer>> divisorGroups = new ArrayList<>();
        for (int i = 0; i <= n + 1; i++) {
            divisorGroups.add(new ArrayList<>());
        }

        for (int divisor = 2; divisor <= n; divisor++) {
            for (int multiple = 2 * divisor; multiple <= n; multiple += divisor) {
                divisorGroups.get(multiple).add(divisor);
            }
        }

        int[] F = new int[n + 1];
        F[1] = 1;
        if (n >= 2) {
            F[2] = 2;
        }

        for (int index = 3; index <= n; index++) {
            F[index] = (2 * F[index - 1] + F[index / (index - 1)]) % M;
            int totalDiff = 0;
            for (int d : divisorGroups.get(index)) {
                if (d >= 2 && d <= index - 2) {
                    totalDiff += F[index / d] - F[(index - 1) / d];
                }
            }
            F[index] = (F[index] + totalDiff) % M;
        }

        System.out.println(F[n] % M);
        scanner.close();
    }
}
